using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table for nibble bit-reversal (used by SIMD paths).
    // Index 0..15 maps to the bit-reversed nibble value.
    private static ReadOnlySpan<byte> NibbleLut => new byte[]
    {
        0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
        0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
    };

    // Full 256-entry scalar lookup table for tail processing.
    private static readonly byte[] ScalarLut = BuildScalarLut();

    private static byte[] BuildScalarLut()
    {
        var lut = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            int b = i;
            b = ((b & 0xF0) >> 4) | ((b & 0x0F) << 4);
            b = ((b & 0xCC) >> 2) | ((b & 0x33) << 2);
            b = ((b & 0xAA) >> 1) | ((b & 0x55) << 1);
            lut[i] = (byte)b;
        }
        return lut;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static void ReverseInPlace(Span<byte> data)
    {
        if (Avx2.IsSupported)
        {
            ReverseAvx2(data);
        }
        else if (Ssse3.IsSupported)
        {
            ReverseSsse3(data);
        }
        else if (AdvSimd.IsSupported)
        {
            ReverseNeon(data);
        }
        else
        {
            ReverseScalar(data);
        }
    }

    private static void ReverseAvx2(Span<byte> data)
    {
        var lowNibbleMask = Vector256.Create((byte)0x0F);
        var lut = Vector256.Create(
            0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
            0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F,
            0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
            0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F);

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int len = data.Length;

        for (; i + 32 <= len; i += 32)
        {
            var vec = Unsafe.ReadUnaligned<Vector256<byte>>(ref Unsafe.Add(ref ptr, i));
            var lo = Avx2.And(vec, lowNibbleMask);
            var hi = Avx2.And(Avx2.ShiftRightLogical(vec.AsUInt16(), 4).AsByte(), lowNibbleMask);
            var reversedLo = Avx2.Shuffle(lut, lo);
            var reversedHi = Avx2.Shuffle(lut, hi);
            var result = Avx2.Or(Avx2.ShiftLeftLogical(reversedLo.AsUInt16(), 4).AsByte(), reversedHi);
            Unsafe.WriteUnaligned(ref Unsafe.Add(ref ptr, i), result);
        }

        // Scalar tail
        byte[] scalarLut = ScalarLut;
        for (; i < len; i++)
        {
            Unsafe.Add(ref ptr, i) = scalarLut[Unsafe.Add(ref ptr, i)];
        }
    }

