            var reversedHi = Ssse3.Shuffle(lut, hi);
            var result = Sse2.Or(Sse2.ShiftLeftLogical(reversedLo.AsUInt16(), 4).AsByte(), reversedHi);
            Unsafe.WriteUnaligned(ref Unsafe.Add(ref ptr, i), result);
        }

