            var reversedHi = AdvSimd.Arm64.VectorTableLookup(lut, hi);
            var result = AdvSimd.Or(AdvSimd.ShiftLeftLogical(reversedLo, 4), reversedHi);
            Unsafe.WriteUnaligned(ref Unsafe.Add(ref ptr, i), result);
        }

